<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { platformRequest, type Review } from '../../services/platform'
import type { OutfitScene } from '../../domain/outfit'
import { navigateOutfitLink } from '../../services/outfit'
const props = defineProps<{ modelValue: boolean; scene: OutfitScene }>()
const emit = defineEmits<{ (e: 'update:modelValue', value: boolean): void }>()
const visible = computed({ get: () => props.modelValue, set: value => emit('update:modelValue', value) })
const selected = ref<string[]>([]), multiLayer = ref(false), roles = ref<Record<string, string>>({}), review = ref<Review | null>(null), loading = ref(false), error = ref('')
const items = computed(() => [...new Map(props.scene.elements.filter(e => e.kind !== 'PERSON_PART').map(e => [e.garmentId, e])).values()])
const states: Record<string, string> = { PRESENT: '已有', MISSING: '缺少', CONFLICT: '冲突', UNKNOWN: '资料未确认' }
const accessoryOptions = [{ value: 'ACCESSORY:EAR', label: '耳部' }, { value: 'ACCESSORY:NECK', label: '颈部' }, { value: 'ACCESSORY:WRIST', label: '手腕' }, { value: 'ACCESSORY:HAND_LEFT', label: '左手' }, { value: 'ACCESSORY:HAND_RIGHT', label: '右手' }, { value: 'ACCESSORY:TIE', label: '领带' }]
let generation = 0
async function check() { const ticket = ++generation; loading.value = true; error.value = ''; try { const next = await platformRequest<Review>('/api/outfit-reviews', 'POST', { scene: props.scene, selectedGarmentIds: selected.value, multiLayer: multiLayer.value, wearRoles: roles.value }); if (ticket === generation) review.value = next } catch (e) { if (ticket === generation) error.value = e instanceof Error ? e.message : String(e) } finally { if (ticket === generation) loading.value = false } }
watch(() => props.modelValue, v => { if (v) { selected.value = items.value.map(i => i.garmentId); roles.value = {}; multiLayer.value = false; void check() } })
function info(id: string) { visible.value = false; navigateOutfitLink('/garment/' + id) }
</script>
<template><wd-popup v-model="visible" position="bottom" closable :z-index="35"><view class="sheet"><view class="sheet-head">全身穿搭检查</view><text class="line">选出本次一名人物穿的一套衣物。复制贴纸只计穿一次，展示素材可排除。检查使用已有资料，不消耗 AI 图像额度。</text><wd-checkbox-group v-model="selected"><view v-for="item in items" :key="item.garmentId" class="field"><wd-checkbox :model-value="item.garmentId">{{ item.garmentLabel }}</wd-checkbox></view></wd-checkbox-group><view class="section"><wd-checkbox v-model="multiLayer">明确使用多层穿法</wd-checkbox></view><wd-button class="section" :loading="loading" @click="check">重新检查</wd-button><text v-if="multiLayer" class="line">最多打底＋主体＋外搭，双外套禁止。两层之间都需核对版型、厚薄和穿着用途。</text><view v-if="error" class="notice error">{{ error }}</view><wd-skeleton v-if="loading" :row-col="[{ width: '100%' }, { height: '160rpx' }]" /><template v-else-if="review"><view v-for="issue in review.blockers" :key="issue.message" class="notice error">{{ issue.message }}<text class="line">{{ issue.action }}</text></view><view v-for="issue in review.warnings" :key="issue.code" class="notice warning">{{ issue.message }}</view><view v-for="slot in review.slots" :key="slot.role" class="field"><view class="spread"><text>{{ slot.label }}</text><wd-tag :type="['CONFLICT', 'UNKNOWN'].includes(slot.state) ? 'danger' : slot.state === 'PRESENT' ? 'success' : 'default'" plain>{{ states[slot.state] }}</wd-tag></view><text v-if="!slot.items.length" class="line small">{{ slot.role === 'TOP' || slot.role === 'BOTTOM' ? '连体主体可替代上下装' : '可按需添加' }}</text><view v-for="item in slot.items" :key="item.garmentId"><text class="line">{{ item.label }}</text><wd-picker v-if="multiLayer && ['TOP', 'INNER'].includes(item.role)" :model-value="roles[item.garmentId] || ''" :columns="[{ value: 'TOP', label: '主体上装' }, { value: 'INNER', label: '打底内层' }]" placeholder="选择穿法" @confirm="roles[item.garmentId] = $event.value" /><wd-picker v-if="item.role === 'ACCESSORY'" :model-value="roles[item.garmentId] || ''" :columns="accessoryOptions" placeholder="确认佩戴位置" @confirm="roles[item.garmentId] = $event.value" /><wd-button type="text" size="small" @click="info(item.garmentId)">核对资料</wd-button></view></view><text class="line small">{{ review.blockers.length ? '请修正后再生成 OOTD。自由画板仍可继续编辑。' : '结构检查通过；实际合身程度与生成效果仍需核对。' }}</text></template></view></wd-popup></template>
<style lang="scss" scoped>@import './outfit.scss';</style>
